import {useEffect,useMemo,useState,type FormEvent} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowRight,ArrowLeft,CalendarDays,Check,ChevronDown,Clock3,Heart,Leaf,MapPin,Menu,ShieldCheck,Sparkles,UserRound,Video,Users,Wallet,Mail,Phone,Activity,RefreshCw,Search,Home,Play} from 'lucide-react';
import AdminWorkspace from './AdminWorkspace';
import {ProgramsPage,MeditationPage,ProgressPage,CommunityPage,ProfilePage} from './WellnessExtras';
