type Locale='en'|'si'|'ta';
type User={id:string;name:string;email:string;role:string;branch_id:string|null;locale:Locale};
type Service={id:string;name:string;summary:string;category:string;kind:'private'|'group'|'online';duration_minutes:number;price_cents:number;capacity:number;requires_review:boolean;accent:string};
type Branch={id:string;name:string;address:string;timezone:string;contact:string};
type Practitioner={id:string;name:string;bio:string;qualifications:string;languages:string[];branch_id:string};
